  "summary": "2026年时尚界从利落剪裁向宽松落肩迁移的大趋势明显，箱型T恤、宽腿裤、oversized外套成为主流。refinery29指出A/W 2026的关键词是'chaotic layering'（混乱叠穿）、宽松廓形。T恤设计宜采用宽松落肩版型，搭配大胆印花或纯色，满足东南亚年轻消费者对舒适与街头的双重追求。（印选 11-06 热点重排上架：库内真实历史热点复用，非新研究。）（印选 11-09 热点重排上架：库内真实历史热点复用，非新研究。）",
